#include <stdio.h>
struct Expense { int day; double amount; };
int main(void) {
 struct Expense e = {16, 125.50};
 FILE *f = fopen("expenses.txt", "a");
 if (f == NULL) return 1;
 int ok = fprintf(f, "%d %.2f\n", e.day, e.amount) >= 0;
 if (fclose(f) == EOF) ok = 0;
 return ok ? 0 : 1;
}
